import type { FigureKey, NeedKey } from "@/lib/data-needs";

export type PageHelpKey =
  | "dashboard"
  | "purchase-requests"
  | "suppliers"
  | "purchase-orders"
  | "goods-receipts"
  | "my-advances"
  | "advances"
  | "products"
  | "stock"
  | "stock-counts"
  | "waste"
  | "production"
  | "transfers"
  | "staff-meals"
  | "sales"
  | "closing"
  | "menus"
  | "menus-lab"
  | "consumption"
  | "expenses-analysis"
  | "expenses"
  | "cost"
  | "cost-departments"
  | "cost-leaks"
  | "cost-prices"
  | "month-end";

export type HelpSection = {
  /** The page marks this part with data-help="<id>"; a part not on the page (another view, no permission) is left out. */
  id: string;
  title: string;
  answers: string;
  /** Data this part waits for; it reads "พร้อม" only when all are there. */
  needs: NeedKey[];
  /** What it waits for instead when the shop counts profit by recipe (สูตรอาหาร). */
  needsRecipe?: NeedKey[];
  /** Drawn taller in the page map (a chart or a table). */
  tall?: true;
  /** What it means, for a reader who was never in our conversation (ระบบตัดแทน, ของแปรรูป …). */
  more?: string;
  /** When the part appears — listed with this when the page has not drawn it now. */
  when?: string;
};

export type HelpFormula = {
  name: string;
  /** "rule": how the system decides a status, colour or flag — not a figure. */
  kind?: "rule";
  formula: string;
  /** The part the number sits in — "ดูบนหน้า" rings it. */
  part?: string;
  /** The working in words, one step a line. */
  steps?: string[];
  /** The working with figures from a made-up shop. */
  worked?: [string, string][];
  includes?: string[];
  excludes?: string[];
  note?: string;
};
export type HelpFeed = { to: string; href: string; what: string };

export type PageHelpCopy = {
  title: string;
  /** The page's address — how a tab bar names its sibling pages' "?". */
  path: string;
  question: string;
  /** Round 1: example figures from a made-up shop. */
  pictures: FigureKey[];
  pictureText: string;
  /** A NEEDS key shows this shop's live status; any other string is shown as written. */
  uses: (NeedKey | string)[];
  outputs: string[];
  why: string;
  sections?: HelpSection[];
  /** Rows of section ids, top to bottom, as the page lays them out. */
  layout?: string[][];
  formulas?: HelpFormula[];
  feeds?: HelpFeed[];
  /** The right column's heading when the page passes nothing on (the dashboard): "ดูรายละเอียดต่อที่". */
  feedsLabel?: string;
  example?: { title: string; rows: [string, string][]; note: string };
};

